 0.08);\n    position: relative;\n    overflow: visible;\n}\n\n.zoom-meeting-card:hover {\n    border-color: #2D8CFF;\n    box-shadow: 0 12px 30px rgba(45, 140, 240, 0.4);\n    transform: translateY(-4px);\n}\n\n.zoom-episode-badge {\n    position: absolute;\n    top: -12px;\n    right: 20px;\n    z-index: 10;\n}\n\n.episode-tag {\n    display: inline-block;\n    background: linear-gradient(135deg, #2D8CFF, #5E35B1);\n    color: white;\n    padding: 8px 16px;\n    border-radius: 20px;\n    font-size: 0.9rem;\n    font-weight: 800;\n    letter-spacing: 1px;\n    box-shadow: 0 6px 16px rgba(45, 140, 240, 0.5);\n}\n\n.zoom-meeting-info {\n    display: flex;\n    gap: 12px;\n    margin-top: 12px;\n    flex-wrap: wrap;\n}\n\n.info-badge {\n    display: inline-flex;\n    align-items: center;\n    gap: 6px;\n    background: rgba(255,255,255,0.1);\n    border: 1px solid rgba(255,255,255,0.2);\n    padding: 6px 12px;\n    border-radius: 12px;\n    font-size: 0.85rem;\n    color: var(--text-secondary);\n}\n\n.info-badge i {\n    color: var(--accent-gold);\n}\n\n.btn-zoom-join {\n    width: 100%;\n    background: linear-gradient(135deg, #2D8CFF, #5E35B1);\n    color: white;\n    text-decoration: none;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    gap: 10px;\n    padding: 14px 24px;\n    font-size: 1rem;\n    box-shadow: 0 6px 18px rgba(45, 140, 240, 0.4);\n}\n\n.btn-zoom-join:hover {\n    background: linear-gradient(135deg, #1a7ae8, #4a2c8e);\n    box-shadow: 0 8px 24px rgba(45, 140, 240, 0.5);\n    transform: translateY(-2px);\n}\n\n/* Ajustes Responsivos para Zoom */\n@media (max-width: 768px) {\n    .zoom-details {\n        flex-direction: column;\n        gap: 8px;\n    }\n    \n    .zoom-episode-badge {\n        top: -10px;\n        right: 10px;\n    }\n    \n    .episode-tag {\n        font-size: 0.8rem;\n        padding: 6px 12px;\n    }\n}\n\n/* Estilos Originais do index.php (copiados para manter consist\u00eancia) */\n:root {\n    --brand-purple: #8e44ad;\n    --brand-purple-dark: #5e3370;\n    --brand-purple-light: #a569bd;\n    --accent-gold: #f39c12;\n    --accent-green: #27ae60;\n    --accent-red: #e74c3c;\n    --text-primary: #ffffff;\n    --text-secondary: #f0f0f0;\n    --text-muted: #d4d4d4;\n    --glass-bg: rgba(255, 255, 255, 0.05);\n    --glass-border: rgba(255, 255, 255, 0.15);\n    --glass-hover-bg: rgba(142, 68, 173, 0.1);\n    --glass-player-bg: rgba(0,0,0,0.1);\n}\n\nbody {\n    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;\n    background-color: #18181c;\n    color: var(--text-primary);\n    margin: 0;\n    padding: 0;\n    line-height: 1.6;\n    overflow-x: hidden;\n}\n\n.main-content {\n    padding: 20px;\n    max-width: 1400px;\n    margin: 0 auto;\n    box-sizing: border-box;\n}\n\n.glass-hero {\n    background: var(--glass-bg);\n    border: 1px solid var(--glass-border);\n    border-radius: 20px;\n    padding: 40px 30px;\n    margin-bottom: 40px;\n    backdrop-filter: blur(15px);\n    text-align: center;\n    position: relative;\n    overflow: hidden;\n}\n\n.glass-hero::before {\n    content: '';\n    position: absolute;\n    top: -1px;\n    left: -1px;\n    right: -1px;\n    bottom: -1px;\n    background: inherit;\n    border-radius: 20px;\n    box-shadow: inset 0 0 0 1px var(--glass-border);\n    z-index: -1;\n}\n\n.hero-content h1 {\n    font-size: 2.8rem;\n    margin-bottom: 15px;\n    color: var(--text-primary);\n    text-shadow: 0 4px 12px rgba(0, 0, 0, 0.3);\n}\n\n.hero-content p {\n    font-size: 1.2rem;\n    color: var(--text-secondary);\n    margin-bottom: 25px;\n}\n\n.cta-btn {\n    display: inline-flex;\n    align-items: center;\n    gap: 8px;\n    padding: 14px 28px;\n    font-size: 1.1rem;\n    font-weight: bold;\n    border-radius: 30px;\n    background: var(--brand-purple);\n    color: #fff;\n    text-decoration: none;\n    box-shadow: 0 6px 18px rgba(142, 68, 173, 0.6);\n    transition: transform 0.3s ease, box-shadow 0.3s ease, background 0.3s ease;\n    border: none;\n    cursor: pointer;\n}\n\n.cta-btn:hover {\n    background: var(--brand-purple-dark);\n    box-shadow: 0 8px 22px rgba(142, 68, 173, 0.7);\n    transform: translateY(-2px);\n}\n\n.video-card {\n    background: var(--glass-bg);\n    border: 1px solid var(--glass-border);\n    border-radius: 20px;\n    backdrop-filter: blur(10px);\n    box-shadow: 0 6px 20px rgba(0,0,0,0.3);\n    display: flex;\n    flex-direction: column;\n}\n\n.card-header {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    padding: 20px 20px 15px;\n    border-bottom: 1px solid var(--glass-border);\n    background: var(--glass-hover-bg);\n}\n\n.card-header h2 {\n    margin: 0;\n    color: var(--text-primary);\n    font-size: 1.3rem;\n    display: flex;\n    align-items: center;\n    gap: 10px;\n}\n\n.live-container {\n    display: grid;\n    grid-template-columns: 2fr 1fr;\n    gap: 24px;\n    margin-bottom: 40px;\n    align-items: stretch;\n}\n\n.player-section {\n    min-height: 0;\n    display: flex;\n    flex-direction: column;\n}\n\n.player-card {\n    flex: 1;\n    display: flex;\n    flex-direction: column;\n}\n\n.live-player {\n    flex: 1;\n    display: flex;\n    flex-direction: column;\n    height: 100%;\n}\n\n.player-container {\n    flex: 1;\n    min-height: 400px;\n    background: #000;\n    border-radius: 12px;\n    overflow: hidden;\n    position: relative;\n}\n\n.player-container iframe {\n    width: 100%;\n    height: 100%;\n    border: none;\n}\n\n.player-controls {\n    display: flex;\n    gap: 12px;\n    padding: 16px;\n    background: var(--glass-player-bg);\n    border-top: 1px solid var(--glass-border);\n}\n\n.control-btn {\n    background: var(--glass-bg);\n    border: 1px solid var(--glass-border);\n    color: var(--text-secondary);\n    padding: 8px 16px;\n    border-radius: 8px;\n    font-size: 0.9rem;\n    cursor: pointer;\n    transition: all 0.3s ease;\n    backdrop-filter: blur(10px);\n}\n\n.control-btn:hover {\n    background: var(--brand-purple);\n    color: #fff;\n    transform: translateY(-2px);\n}\n\n.control-btn.small {\n    padding: 6px 10px;\n    font-size: 0.8rem;\n}\n\n.chat-section {\n    min-height: 0;\n    display: flex;\n    flex-direction: column;\n}\n\n.chat-card {\n    flex: 1;\n    display: flex;\n    flex-direction: column;\n    height: 100%;\n}\n\n.chat-header {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    padding: 16px;\n    border-bottom: 1px solid var(--glass-border);\n    background: var(--glass-hover-bg);\n}\n\n.chat-header h3 {\n    margin: 0;\n    color: #fff;\n    font-size: 1.1rem;\n}\n\n.chat-controls {\n    display: flex;\n    gap: 8px;\n}\n\n.chat-messages {\n    flex: 1;\n    padding: 16px;\n    overflow-y: auto;\n    display: flex;\n    flex-direction: column;\n    gap: 12px;\n    scrollbar-width: thin;\n    scrollbar-color: var(--brand-purple-light) transparent;\n}\n\n.chat-message {\n    background: var(--glass-bg);\n    border: 1px solid var(--glass-border);\n    border-radius: 12px;\n    padding: 12px;\n    backdrop-filter: blur(10px);\n    animation: slideIn 0.3s ease;\n}\n\n@keyframes slideIn {\n    0% { opacity: 0; transform: translateY(20px); }\n    50% { opacity: 0.5; }\n    100% { opacity: 1; transform: translateY(0); }\n}\n\n.message-header {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    margin-bottom: 6px;\n}\n\n.username {\n    color: var(--brand-purple);\n    font-weight: 600;\n    font-size: 0.9rem;\n}\n\n.timestamp {\n    color: #999;\n    font-size: 0.8rem;\n}\n\n.message-content {\n    color: var(--text-secondary);\n    font-size: 0.9rem;\n    line-height: 1.4;\n    word-wrap: break-word;\n}\n\n.message-actions {\n    margin-top: 8px;\n    padding-top: 8px;\n    border-top: 1px solid var(--glass-border);\n}\n\n.btn-overlay {\n    background: rgba(52, 152, 219, 0.2);\n    border: 1px solid rgba(52, 152, 219, 0.3);\n    color: #3498db;\n    padding: 4px 8px;\n    border-radius: 6px;\n    font-size: 0.8rem;\n    cursor: pointer;\n    transition: all 0.3s ease;\n}\n\n.btn-overlay:hover {\n    background: rgba(52, 152, 219, 0.3);\n    transform: translateY(-1px);\n}\n\n.system-message {\n    background: rgba(46, 204, 113, 0.2);\n    border: 1px solid rgba(46, 204, 113, 0.3);\n    color: #2ecc71;\n    padding: 12px;\n    border-radius: 8px;\n    text-align: center;\n    font-size: 0.9rem;\n}\n\n.chat-offline-message {\n    background: rgba(149, 165, 166, 0.2);\n    border: 1px solid rgba(149, 165, 166, 0.3);\n    color: #95a5a6;\n    padding: 12px;\n    border-radius: 8px;\n    text-align: center;\n    font-size: 0.9rem;\n}\n\n.chat-input-container {\n    padding: 16px;\n    border-top: 1px solid var(--glass-border);\n    background: var(--glass-player-bg);\n    margin-top: auto;\n}\n\n.chat-input-group {\n    display: flex;\n    gap: 12px;\n    align-items: center;\n}\n\n.chat-input-group input {\n    flex: 1;\n    padding: 12px;\n    border-radius: 20px;\n    border: 1px solid var(--glass-border);\n    background: rgba(255,255,255,0.06);\n    color: var(--text-secondary);\n    font-size: 0.9rem;\n}\n\n.chat-input-group input:focus {\n    outline: none;\n    border-color: var(--brand-purple);\n    box-shadow: 0 0 0 2px rgba(142, 68, 173, 0.2);\n}\n\n.send-btn {\n    background: var(--brand-purple);\n    border: none;\n    color: #fff;\n    width: 44px;\n    height: 44px;\n    border-radius: 50%;\n    cursor: pointer;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    transition: all 0.3s ease;\n    font-size: 1rem;\n}\n\n.send-btn:hover {\n    background: var(--brand-purple-dark);\n    transform: scale(1.1);\n}\n\n.live-status {\n    display: inline-flex;\n    align-items: center;\n    gap: 8px;\n    padding: 8px 16px;\n    border-radius: 20px;\n    font-weight: 600;\n    font-size: 0.9rem;\n    margin-top: 20px;\n}\n\n.live-active {\n    background: rgba(46, 204, 113, 0.2);\n    border: 1px solid rgba(46, 204, 113, 0.3);\n    color: #2ecc71;\n}\n\n.live-offline {\n    background: rgba(149, 165, 166, 0.2);\n    border: 1px solid rgba(149, 165, 166, 0.3);\n    color: #95a5a6;\n}\n\n.pulse {\n    animation: pulse 2s infinite;\n}\n\n@keyframes pulse {\n    0% { opacity: 1; }\n    50% { opacity: 0.5; }\n    100% { opacity: 1; }\n}\n\n.offline-player {\n    flex: 1;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    background: linear-gradient(135deg, #2c2c2e, #1c1c1e);\n    border-radius: 12px;\n    min-height: 400px;\n}\n\n.offline-content {\n    text-align: center;\n    padding: 40px;\n}\n\n.offline-content i {\n    font-size: 4rem;\n    color: #666;\n    margin-bottom: 20px;\n}\n\n.offline-content h3 {\n    color: #fff;\n    margin-bottom: 16px;\n    font-size: 1.5rem;\n}\n\n.offline-content p {\n    color: #ccc;\n    margin-bottom: 12px;\n    line-height: 1.5;\n}\n\n.social-links {\n    display: flex;\n    gap: 16px;\n    justify-content: center;\n    margin-top: 24px;\n}\n\n.social-link {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    padding: 8px 16px;\n    background: var(--glass-bg);\n    border: 1px solid var(--glass-border);\n    border-radius: 20px;\n    color: var(--text-secondary);\n    text-decoration: none;\n    font-size: 0.9rem;\n    transition: all 0.3s ease;\n}\n\n.social-link:hover {\n    background: var(--brand-purple);\n    color: #fff;\n    transform: translateY(-2px);\n}\n\n.overlay-preview {\n    margin-top: 24px;\n}\n\n.overlay-content {\n    min-height: 100px;\n    background: rgba(0,0,0,0.3);\n    border-radius: 8px;\n    padding: 20px;\n    border: 2px dashed var(--glass-border);\n    display: flex;\n    flex-direction: column;\n    justify-content: center;\n    align-items: center;\n    text-align: center;\n    color: var(--text-muted);\n}\n\n.overlay-content .empty-state {\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    gap: 12px;\n}\n\n.overlay-content .empty-state i {\n    font-size: 2rem;\n    color: var(--brand-purple-light);\n}\n\n.schedule-card h2 {\n    margin: 0 20px 10px 20px;\n}\n\n.schedule-instruction {\n    text-align: center;\n    color: var(--accent-gold);\n    margin-top: 15px;\n    margin-bottom: 30px;\n    font-size: 1.15rem;\n    font-weight: 600;\n    line-height: 1.5;\n}\n\n.instruction-highlight {\n    font-size: 1.25rem;\n}\n\n.lectures-grid {\n    display: grid;\n    grid-template-columns: repeat(3, 1fr);\n    gap: 30px;\n    margin: 30px 0;\n}\n\n.lecture-card {\n    border: 2px solid transparent;\n    border-radius: 20px;\n    padding: 20px;\n    background: rgba(255,255,255,0.08);\n    transition: box-shadow 0.28s ease, border-color 0.28s ease, transform 0.28s ease;\n    cursor: default;\n    display: flex;\n    flex-direction: column;\n    justify-content: space-between;\n}\n\n.lecture-card:hover {\n    border-color: var(--brand-purple);\n    box-shadow: 0 10px 20px rgba(142, 68, 173, 0.3);\n}\n\n.lecture-image-container {\n    position: relative;\n    width: 100%;\n    padding-bottom: 56.25%;\n    overflow: hidden;\n    border-radius: 12px;\n    margin-bottom: 16px;\n}\n\n.lecture-image {\n    position: absolute;\n    top: 0;\n    left: 0;\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n}\n\n.lecture-info {\n    flex-grow: 1;\n}\n\n.lecture-datetime {\n    display: flex;\n    align-items: center;\n    gap: 12px;\n    margin-bottom: 12px;\n}\n\n.lecture-date {\n    background: var(--brand-purple);\n    color: white;\n    padding: 6px 12px;\n    border-radius: 12px;\n    font-size: 0.9rem;\n    font-weight: 700;\n    display: inline-block;\n}\n\n.lecture-time {\n    background: var(--accent-gold);\n    color: white;\n    padding: 6px 12px;\n    border-radius: 12px;\n    font-size: 0.9rem;\n    font-weight: 700;\n    display: inline-block;\n}\n\n.lecture-title {\n    font-size: 1.2rem;\n    color: var(--text-primary);\n    margin: 8px 0 10px;\n    font-weight: 700;\n    line-height: 1.25rem;\n    display: -webkit-box;\n    -webkit-line-clamp: 3;\n    -webkit-box-orient: vertical;\n    overflow: hidden;\n    text-overflow: ellipsis;\n    max-height: calc(1.25rem * 3);\n    min-height: calc(1.25rem * 3);\n}\n\n.lecture-speaker {\n    display: flex;\n    align-items: flex-start;\n    gap: 8px;\n    font-size: 1.15rem;\n    color: var(--brand-purple-dark);\n    margin-bottom: 10px;\n}\n\n.lecture-speaker span {\n    color: var(--accent-gold) !important;\n    font-weight: 700;\n    line-height: 1.3rem;\n    display: -webkit-box;\n    -webkit-line-clamp: 2;\n    -webkit-box-orient: vertical;\n    overflow: hidden;\n    text-overflow: ellipsis;\n    min-height: calc(1.3rem * 2);\n    max-height: calc(1.3rem * 2);\n}\n\n.lecture-speaker i {\n    color: var(--accent-gold);\n    margin-top: 2px;\n}\n\n.lecture-summary {\n    color: var(--text-secondary);\n    font-size: 0.95rem;\n    line-height: 1.4rem;\n    display: -webkit-box;\n    -webkit-line-clamp: 5;\n    -webkit-box-orient: vertical;\n    overflow: hidden;\n    text-overflow: ellipsis;\n    max-height: calc(1.4rem * 5);\n    margin: 0;\n}\n\n.schedule-actions-bottom {\n    margin-top: 20px;\n    text-align: center;\n}\n\n.agenda-divider {\n    border: none;\n    height: 1px;\n    background-color: rgba(255, 255, 255, 0.15);\n    margin: 20px 0 15px;\n}\n\n.agenda-title {\n    text-align: center;\n    font-size: 0.95rem;\n    font-weight: 600;\n    color: var(--text-secondary);\n    margin: 0 0 15px 0;\n}\n\n.agenda-buttons-container {\n    display: flex;\n    gap: 10px;\n    justify-content: center;\n}\n\n.btn-agenda {\n    flex: 1;\n    padding: 10px 15px;\n    font-size: 0.9rem;\n    justify-content: center;\n    text-decoration: none;\n}\n\n.btn-google-cal {\n    background: linear-gradient(135deg, #4285F4, #357ae8);\n    box-shadow: 0 4px 15px rgba(66, 133, 244, 0.4);\n}\n\n.btn-apple-cal {\n    background: linear-gradient(135deg, #f0f0f0, #e0e0e0);\n    color: #333;\n    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.2);\n}\n\n.btn-agenda:not(.clicked):hover {\n    transform: translateY(-2px);\n    box-shadow: 0 6px 16px rgba(0,0,0,0.3);\n}\n\n.btn-google-cal:not(.clicked):hover {\n    background: linear-gradient(135deg, #357ae8, #2a62bc);\n    box-shadow: 0 8px 20px rgba(53, 122, 184, 0.5);\n}\n\n.btn-apple-cal:not(.clicked):hover {\n    background: linear-gradient(135deg, #e0e0e0, #d0d0d0);\n    color: #222;\n    box-shadow: 0 8px 20px rgba(0,0,0,0.3);\n}\n\n.btn-agenda.clicked {\n    background: linear-gradient(135deg, #2ecc71, #27ae60);\n    color: white;\n    box-shadow: 0 4px 15px rgba(39, 174, 96, 0.5);\n    cursor: default;\n    transform: none !important;\n}\n\n@media (max-width: 1200px) {\n    .lectures-grid {\n        grid-template-columns: repeat(2, 1fr);\n    }\n}\n\n@media (max-width: 768px) {\n    .live-container {\n        grid-template-columns: 1fr;\n        gap: 20px;\n    }\n    .lectures-grid {\n        grid-template-columns: 1fr;\n    }\n    .glass-hero h1 {\n        font-size: 2.2rem;\n    }\n    .glass-hero p {\n        font-size: 1.1rem;\n    }\n    .cta-btn {\n        padding: 12px 24px;\n        font-size: 1rem;\n    }\n}\n</style>\n\n<script>\n// JavaScript original do index.php (copiado)\nconst CURRENT_USER_IS_ADMIN = <?php echo isAdmin() ? 'true' : 'false'; ?>;\nconst CURRENT_USER_NAME = '<?php echo addslashes($_SESSION['user_name'] ?? $_SESSION['nome'] ?? 'Voc\u00ea'); ?>';\n\nlet chatMessages = [];\n\ndocument.addEventListener('DOMContentLoaded', function() {\n    initChatLogic();\n});\n\nfunction initChatLogic() {\n    const chatForm = document.getElementById('chatForm');\n    \n    if (chatForm) {\n        chatForm.addEventListener('submit', function(e) {\n            e.preventDefault();\n\n            const input = document.getElementById('chatInput');\n            const msg = input.value.trim();\n\n            if (!msg) return;\n\n            input.disabled = true;\n            const sendBtn = chatForm.querySelector('.send-btn');\n            const originalContent = sendBtn.innerHTML;\n            sendBtn.innerHTML = '<i class=\"fas fa-spinner fa-spin\"></i>';\n\n            const endpoint = 'chat-save.php';\n            const formData = new FormData(chatForm);\n            \n            fetch(endpoint, {\n                method: 'POST',\n                body: formData\n            })\n            .then(response => {\n                if (response.ok) {\n                    const newMessage = {\n                        id: Date.now(),\n                        user_name: CURRENT_USER_NAME,\n                        message: msg,\n                        created_at: new Date().toISOString(),\n                        isOwn: true,\n                        isAdmin: CURRENT_USER_IS_ADMIN\n                    };\n                    \n                    chatMessages.push(newMessage);\n                    addMessageToChat(newMessage);\n                    input.value = '';\n                } else {\n                    console.error('Erro ao enviar mensagem:', response.statusText);\n                    alert('Erro ao enviar mensagem. Tente novamente.');\n                }\n            })\n            .catch(error => {\n                console.error('Erro de rede:', error);\n                alert('Erro de conex\u00e3o. Verifique sua rede.');\n            })\n            .finally(() => {\n                input.disabled = false;\n                sendBtn.innerHTML = originalContent;\n                scrollChatToBottom();\n            });\n        });\n    }\n    \n    loadRealMessagesFromApi();\n}\n\nfunction loadRealMessagesFromApi() {\n    addInitialMessages();\n}\n\nfunction addInitialMessages() {\n    const container = document.getElementById('chatMessagesContainer');\n    if (container.children.length === 0) {\n        const initialMessages = [\n            { id: 1, user_name: 'Sistema', message: 'Chat da live iniciado!', created_at: new Date(Date.now() - 30000).toISOString(), isSystem: true },\n            { id: 2, user_name: 'Admin', message: 'Bem-vindos \u00e0 transmiss\u00e3o ao vivo!', created_at: new Date(Date.now() - 120000).toISOString(), isAdmin: true }\n        ];\n        \n        initialMessages.forEach(msg => {\n            chatMessages.push(msg);\n            addMessageToChat(msg);\n        });\n        scrollChatToBottom();\n    }\n}\n\nfunction addMessageToChat(msg) {\n    const container = document.getElementById('chatMessagesContainer');\n    const messageElement = document.createElement('div');\n    messageElement.className = 'chat-message';\n    \n    const time = new Date(msg.created_at).toLocaleTimeString('pt-BR', {hour: '2-digit', minute: '2-digit'});\n    \n    let overlayButton = '';\n    if (CURRENT_USER_IS_ADMIN && !msg.isSystem) {\n        overlayButton = `\n        <div class=\"message-actions\">\n        <button class=\"btn-overlay\" data-id=\"${msg.id}\">\n        <i class=\"fas fa-tv\"></i> Exibir na Tela\n        </button>\n        </div>\n        `;\n    }\n    \n    messageElement.innerHTML = `\n    <div class=\"message-header\">\n    <strong class=\"username\">${escapeHtml(msg.user_name)}</strong>\n    <small class=\"timestamp\">[${time}]</small>\n    </div>\n    <div class=\"message-content\">\n    ${escapeHtml(msg.message)}\n    </div>\n    ${overlayButton}\n    `;\n    \n    container.appendChild(messageElement);\n    \n    if (overlayButton) {\n        addOverlayButtonEvents();\n    }\n}\n\nfunction addOverlayButtonEvents() {\n    document.querySelectorAll('.btn-overlay:not([data-bound])').forEach(btn => {\n        btn.setAttribute('data-bound', 'true');\n        btn.addEventListener('click', function() {\n            const messageText = this.closest('.chat-message').querySelector('.message-content').textContent;\n            const username = this.closest('.chat-message').querySelector('.username').textContent;\n            \n            const overlayContent = document.getElementById('overlayMessage');\n            if (overlayContent) {\n                overlayContent.innerHTML = `\n                <div class=\"overlay-message\" style=\"background: rgba(142, 68, 173, 0.2); border: 1px solid rgba(142, 68, 173, 0.3); padding: 16px; border-radius: 8px; color: #fff;\">\n                <strong style=\"color: var(--brand-purple);\">${username}:</strong> ${messageText}\n                </div>\n                `;\n            }\n            \n            this.innerHTML = '<i class=\"fas fa-check\"></i> Enviado!';\n            this.style.background = 'rgba(46, 204, 113, 0.3)';\n            this.style.color = '#2ecc71';\n            \n            setTimeout(() => {\n                this.innerHTML = '<i class=\"fas fa-tv\"></i> Exibir na Tela';\n                this.style.background = 'rgba(52, 152, 219, 0.2)';\n                this.style.color = '#3498db';\n            }, 2000);\n        });\n    });\n}\n\nfunction scrollChatToBottom() {\n    const chatContainer = document.getElementById('chatMessages');\n    setTimeout(() => {\n        chatContainer.scrollTop = chatContainer.scrollHeight;\n    }, 50);\n}\n\nfunction escapeHtml(unsafe) {\n    if (!unsafe) return '';\n    return unsafe\n    .replace(/&/g, \"&amp;\")\n    .replace(/</g, \"&lt;\")\n    .replace(/>/g, \"&gt;\")\n    .replace(/\"/g, \"&quot;\")\n    .replace(/'/g, \"&#039;\");\n}\n\nfunction toggleChat() {\n    const chatMessages = document.getElementById('chatMessages');\n    if (chatMessages.style.display === 'none' || chatMessages.style.display === '') {\n        chatMessages.style.display = 'flex';\n    } else {\n        chatMessages.style.display = 'none';\n    }\n}\n\nfunction clearChat() {\n    if (confirm('Limpar todas as mensagens do chat? Esta a\u00e7\u00e3o n\u00e3o pode ser desfeita.')) {\n        chatMessages = [];\n        document.getElementById('chatMessagesContainer').innerHTML = '';\n    }\n}\n\nfunction clearOverlay() {\n    const overlayContent = document.getElementById('overlayMessage');\n    if (overlayContent) {\n        overlayContent.innerHTML = `\n        <div class=\"empty-state\">\n        <i class=\"fas fa-tv\"></i>\n        <p>Nenhuma mensagem selecionada para o overlay</p>\n        </div>\n        `;\n    }\n}\n\nfunction toggleFullscreen() {\n    const playerContainer = document.querySelector('.player-container');\n    if (playerContainer && playerContainer.requestFullscreen) {\n        playerContainer.requestFullscreen();\n    } else {\n        alert('Seu navegador n\u00e3o suporta tela cheia neste elemento ou n\u00e3o h\u00e1 player ativo.');\n    }\n}\n\nfunction togglePictureInPicture() {\n    const videoElement = document.querySelector('.player-container iframe');\n    if (videoElement && videoElement.requestPictureInPicture) {\n        videoElement.requestPictureInPicture()\n            .catch(error => {\n                console.error('Erro ao tentar PiP:', error);\n                alert('N\u00e3o foi poss\u00edvel ativar o Picture-in-Picture.');\n            });\n    } else {\n        alert('Seu navegador n\u00e3o suporta Picture-in-Picture para este elemento.');\n    }\n}\n\nfunction escapeIcs(value) {\n    if (!value) return '';\n    return value\n        .replace(/\\\\/g, '\\\\\\\\')\n        .replace(/,/g, '\\\\,')\n        .replace(/;/g, '\\\\;')\n        .replace(/\\n/g, '\\\\n')\n        .replace(/\\r/g, '');\n}\n\nfunction showFeedback(btn, isGoogle) {\n    btn.innerHTML = `<i class=\"fas fa-check\"></i> ${isGoogle ? 'Aberto' : 'Baixado'}`;\n    btn.classList.add('clicked');\n    btn.onclick = function(event) { event.preventDefault(); };\n    btn.style.cursor = 'default';\n}\n\nfunction generateGoogleCalendarLink(e) {\n    e.preventDefault();\n    const btn = e.currentTarget;\n    const eventData = JSON.parse(btn.getAttribute('data-event'));\n\n    const baseUrl = 'https://www.google.com/calendar/render?action=TEMPLATE';\n    const params = new URLSearchParams({\n        'text': `${eventData.title} com ${eventData.speaker}`,\n        'dates': `${eventData.start_utc.replace(/\\.000Z$/, 'Z')}/${eventData.end_utc.replace(/\\.000Z$/, 'Z')}`,\n        'details': `${eventData.description}\\n\\nPalestrante: ${eventData.speaker}\\n\\nAssista em: https://translators101.com/v/live-stream`,\n        'location': 'Translators101 - Online'\n    });\n    \n    window.open(baseUrl + '&' + params.toString(), '_blank');\n    showFeedback(btn, true);\n}\n\nfunction generateIcs(e) {\n    e.preventDefault();\n    const btn = e.currentTarget;\n    const eventData = JSON.parse(btn.getAttribute('data-event'));\n\n    const title = eventData.title || \"Evento Translators101\";\n    const description = eventData.description || \"Palestra Exclusiva da Translators101\";\n    const speaker = eventData.speaker || \"Palestrante\";\n    const start = eventData.start;\n    const end = eventData.end;\n    const reminder = eventData.reminder;\n\n    const escapedTitle = escapeIcs(title);\n    const escapedDescription = escapeIcs(description);\n    const escapedSpeaker = escapeIcs(speaker);\n\n    const icsContent = [\n        'BEGIN:VCALENDAR',\n        'VERSION:2.0',\n        'PRODID:-//Translators101//Live Reminder//EN',\n        'CALSCALE:GREGORIAN',\n        'METHOD:PUBLISH',\n        'BEGIN:VEVENT',\n        `DTSTART;TZID=America/Sao_Paulo:${start}`,\n        `DTEND;TZID=America/Sao_Paulo:${end}`,\n        `SUMMARY;CHARSET=UTF-8:${escapedTitle} com ${escapedSpeaker}`,\n        `DESCRIPTION;CHARSET=UTF-8:${escapedDescription}\\\\n\\\\nPalestrante: ${escapedSpeaker}\\\\n\\\\nAssista em: https://translators101.com/v/live-stream`,\n        `LOCATION;CHARSET=UTF-8:Translators101 - Online`,\n        `UID:${Date.now()}-${Math.random().toString(36).substring(2, 9)}@translators101.com.br`,\n        `DTSTAMP:${new Date().toISOString().replace(/[-:]|\\.\\d{3}/g, '')}Z`,\n        'BEGIN:VALARM',\n        'ACTION:DISPLAY',\n        `DESCRIPTION;CHARSET=UTF-8:Lembrete: ${escapedTitle}`,\n        `TRIGGER:-PT${reminder}M`,\n        'END:VALARM',\n        'END:VEVENT',\n        'END:VCALENDAR'\n    ].join('\\r\\n');\n    \n    const safeTitle = title.replace(/[\\\\/:\\*?\"<>|]/g, '_').substring(0, 40).trim();\n    const filename = `Lembrete_${safeTitle}.ics`;\n    \n    const blob = new Blob([icsContent], { type: 'text/calendar;charset=utf-8' });\n\n    const link = document.createElement('a');\n    link.href = URL.createObjectURL(blob);\n    link.download = filename;\n    document.body.appendChild(link);\n    link.click();\n    document.body.removeChild(link);\n    \n    showFeedback(btn, false);\n}\n</script>\n"}]